sketches.source:
setcpm(64/4)

// The swamp air: unrelated brown noise in each ear, wide and humid all around you
air: s("brown").slow(8).icorr(.15).lpf(700).gain(.12)

// Bubbles rising from the mud, each one somewhere new around your head
bubbles: s("drip*8?0.5").speed(rand.range(.4, .9)).azimuth(rand.range(-180, 180))
  .distance(2).seed("mud").gain(.14)

// Giant dragonflies circling once every two bars, a little above you
dragonflies: s("insect").slow(2).azimuth(saw.range(-180, 180).slow(2)).elevation(20)
  .distance(1.5).posglide(.2).gain(.12)

// Frogs, or something bigger, croaking on the right
frogs: s("lt ~ [~ lt] ~").speed(.6).lpf(400).azimuth(40).distance(3).gain(.2)

// A far-off call across the water, from the left
call: note("<~ ~ [e3@2 b2@6] ~>").s("sawtooth").mono(1).glide(.3).vowel("oo")
  .lpf(900).attack(.2).sustain(.7).release(1.5).azimuth(-70).distance(12).room(.6).gain(.14)

// A murky pad and a 6 Hz binaural beat: each ear is detuned by 3 Hz. Keep it quiet
pad: note("<[e2,b2,g3] [c2,g2,e3]>").slow(2).s("sawtooth").unison(3).detune(.2)
  .lpf(800).attack(2).release(3).room(.7).gain(.1)
drone: note("[e2,b2]").slow(4).s("sine").binaural(6)
  .attack(3).sustain(1).release(4).gain(.12)

setcpm(84/4)

// The roar: a gritty saw sliding down, through a tube curve and an ah vowel
const roar = (x) => x.s("sawtooth").unison(3).detune(25).mono(1).glide(.3)
  .vowel("ah").curve("tube").drive(12).lpf(1400).attack(.1).sustain(.8).release(1.5)

// Footsteps: over eight bars the distance falls from 30 to 1.5
// and the direction swings from behind you (160 degrees) round to straight ahead
steps: s("lt ~ ~ ~ lt ~ ~ ~").speed(.3).lpf(250).shape(.3)
  .azimuth(isaw.range(0, 160).slow(8)).distance(isaw.range(1.5, 30).slow(8)).posglide(.3)
  .gain(saw.range(.2, .7).slow(8))

// The ferns rustle along the same path
ferns: s("pink*8?0.4").hpf(3000).decay(.05).sustain(0)
  .azimuth(isaw.range(0, 160).slow(8)).distance(isaw.range(1.5, 30).slow(8)).seed("ferns").gain(.05)

// Your heartbeat, in the middle of your head, doubling for the last bars
heart: s("bd ~ bd ~ ~ ~ ~ ~").lpf(150).fast("<1 1 1 1 1 2 2 2>").gain(.4)

// Strings climbing in tremolo as it gets closer
strings: note("d2*8").add("<0 0 1 1 3 3 5 6>").s("sawtooth").unison(2).detune(15)
  .lpf(saw.range(600, 2600).slow(8)).decay(.1).sustain(.4).release(.05).room(.4).gain(.16)

// The roar on the eighth bar, close and dead centre
trex: note("<~ ~ ~ ~ ~ ~ ~ [g1@2 d2@3 a1@3]>").roar().distance(1).room(.5).gain(.24)

setcpm(40/4)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("<g1 g1 eb1 f1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// The giants hum far above your head, drifting slowly from side to side
giants: note("<[g2@3 d3] [c3@4] [bb2@2 f2@2] [g2@4]>").slow(2).s("hum")
  .elevation(60).distance(6).azimuth(sine.range(-40, 40).slow(16)).posglide(.5)
  .attack(2).release(3).gain(.2)

// A calf answers, smaller and lower in the trees, off to the right
calf: note("<~ [d4@3 bb3] ~ ~>").s("hum").elevation(25).azimuth(60).distance(4)
  .attack(1).release(2).gain(.1)

// Wind in the treetops, up where they feed
leaves: s("wind").slow(8).intensity(.2).elevation(50).distance(5).gain(.08)

// A warm pad that barely moves
pad: note("<[g2,d3,bb3] [eb2,bb2,g3]>").slow(8).s("sawtooth").unison(4).detune(.3)
  .attack(6).release(8).lpf(600).room(.8).size(.95).gain(.1)

setcpm(140/4)

// A raptor call: a short, reedy chirp sliding between notes
const raptor = (x) => x.s("sine").timbre("reed").mono(1).glide(.04)
  .attack(.01).decay(.1).sustain(.5).release(.1).room(.3)

// The kick and bass hold the centre while the pack circles
kick: s("bd*4").shape(.2).gain(.75)
bass: note("<a1 a1 c2 g1>").struct("x ~ x x ~ x ~ x").s("sawtooth").lpf(700).lpq(4)
  .decay(.15).sustain(.3).release(.05).gain(.42)
hats: s("[~ hh]*4").hpf(7000).gain(.2)

// Claws on stone: ild leans them right, a seeded coin flip throws some to the left
claws: s("click*16").hpf(2500).ild(10).earswap(irand(2).segment(16)).seed("claws").gain(.18)

// Three raptors: one on your left, one on your right, and one behind you
left: note("<[a5 e6 ~ ~] ~ [c6 a5 ~ ~] ~>").raptor().azimuth(-80).distance(3).gain(.12)
right: note("<~ [e6 a5 ~ ~] ~ [g5 c6 ~ ~]>").raptor().azimuth(80).distance(3).gain(.12)
behind: note("<~ ~ ~ [~ ~ a6 e6]>").raptor().azimuth(170).distance(2).gain(.1)

// Stabbing strings in the middle
stabs: note("<[a3,c4,e4] [a3,c4,e4] [c4,e4,g4] [g3,b3,d4]>").struct("x ~ ~ x ~ ~ x ~")
  .s("sawtooth").unison(2).detune(.15).lpf(2400).decay(.15).sustain(0).gain(.18)

setcpm(88/4)

// earsplit("bands") puts everything below 700 Hz in one ear and above it in the other
drums: s("bd ~ ~ bd ~ ~ bd ~, ~ ~ sd ~ ~ ~ sd ~, hh*8").earsplit("bands").splitfreq(700).gain(.6)

// The stomp itself: big low toms, dead centre
stomp: s("lt ~ ~ ~ lt ~ ~ ~").speed(.4).lpf(300).shape(.3).gain(.5)

// earsplit("harmonics") alternates the brass partials: each ear hears a thinner stab
brass: note("<[e2,b2,e3,g3] [e2,b2,e3,g3] [c2,g2,c3,e3] [d2,a2,d3,f#3]>").struct("x ~ ~ x ~ ~ ~ ~")
  .s("sawtooth").earsplit("harmonics").lpf(1400).lpenv(2).lpattack(.03)
  .attack(.02).decay(.4).sustain(.3).release(.3).room(.4).gain(.22)

// The tail spikes swing from ear to ear on delays under a millisecond
spikes: s("rim*8").speed(.7).itd(sine.range(-.6, .6).slow(1)).hpf(1200).gain(.2)

// A plain, centred bass
bass: note("<e1 e1 c1 d1>").struct("x ~ x ~ ~ x ~ ~").s("sawtooth").lpf(500)
  .curve("tube").drive(8).decay(.3).sustain(.4).release(.1).gain(.36)

setcpm(72/4)

// earsh raises the right ear and lowers the left by half the value each
// 2 cents beats slowly; 30 cents widens into a whole herd
herd: note("[f2,c3]").s("sawtooth").vowel("oo").earsh("<2 6 12 30>")
  .lpf(700).attack(1).sustain(1).release(1).gain(.18)

// Hooves falling all around you, each step somewhere new
hooves: s("lt*8?0.5").speed(.5).lpf(400).azimuth(rand.range(-180, 180)).distance(rand.range(2, 8))
  .seed("herd").gain(.2)

// The dust they kick up: wide and diffuse
dust: s("pink").slow(8).icorr(.2).hpf(800).lpf(3000).gain(.03)

// A horn calling across the valley, from the left
horn: note("<[c4@2 f4@6] ~ [a4@3 g4 f4@4] ~>").s("sawtooth").lpf(900).lpenv(1).lpattack(.12)
  .attack(.1).sustain(.8).release(.8).azimuth(-60).distance(10).space("outdoor").gain(.18)

// Plains music in the middle: F, Dm, Bb, C
piano: note("<[f3 c4 a4 c4] [d3 a3 f4 a3] [bb2 f3 d4 f3] [c3 g3 e4 g3]>")
  .s("triangle").timbre("soft").attack(.005).decay(.8).sustain(.1).release(.8).room(.5).gain(.24)
bass: note("<f2 d2 bb1 c2>").s("sine").attack(.05).sustain(.7).release(.4).gain(.34)

setcpm(76/4)

// Lava hissing: unrelated noise in each ear, wide and all around
lava: s("pink").slow(8).icorr(.1).hpf(1500).lpf(5000).gain(.03)

// The ground rumbling beneath you, centred
rumble: s("brown").slow(4).lpf(sine.range(80, 260).slow(8)).gain(.22)

// Fire on the slope to your left
fire: s("fire").slow(4).intensity(.6).density(14).azimuth(-60).distance(4).gain(.2)

// From about 1 to 30 ms the stabs stay on the leading side but grow wider each bar
stabs: note("[c3,eb3,g3,bb3]").struct("x ~ ~ x ~ ~ x ~").s("sawtooth").unison(2).detune(.15)
  .itd("<1 8 15 25>").lpf(2000).decay(.25).sustain(0).room(.4).gain(.2)

// The strings step through the interaural phase: 0 centred, 90 looser, 180 diffuse
pad: note("<[c3,eb3,g3] [ab2,c3,eb3] [f2,ab2,c3] [g2,b2,d3]>").s("sawtooth").unison(2).detune(.1)
  .iphase("<0 90 180 90>").lpf(1000).attack(1).sustain(1).release(2).gain(.12)

// Eruption drums, and a bass under the mountain
drums: s("lt ~ [~ lt] ~, ~ ~ mt ~, <~ ~ ~ cr>").speed(.7).lpf(1200).room(.6).gain(.42)
bass: note("<c2 ab1 f1 g1>").s("sine").shape(.2).attack(.05).sustain(.7).release(.4).gain(.38)

setcpm(52/4)

// irate turns the phase between the ears, in turns per second: all below 3 Hz
drone: note("[d2,a2]").s("sawtooth").irate("<.25 .5 1 2>").lpf(500)
  .attack(2).sustain(1).release(2).gain(.18)

// The surface, far above and muffled by the water
surface: s("surf").slow(8).intensity(.4).elevation(70).distance(8).occlude(.7).gain(.2)

// Bubbles drifting past, slowly rising around you
bubbles: s("drip*8?0.4").speed(rand.range(.3, .7)).azimuth(sine.range(-120, 120).slow(8))
  .elevation(saw.range(-20, 40)).distance(2).seed("bubbles").space("hall").gain(.12)

// The mosasaur: a long, gliding call from the dark behind you
mosasaur: note("<~ [a1@2 d2@4 c2@2] ~ ~>").s("sawtooth").mono(1).glide(.5).vowel("oo")
  .lpf(600).attack(.5).sustain(.8).release(2).azimuth(150).distance(10).space("hall").gain(.22)

// Light filtering down from above
light: n("<[4 ~ ~ 2] [~ 5 ~ ~] [7 ~ ~ 4] [~ ~ 2 ~]>").scale("D:minor").transpose(12)
  .s("triangle").timbre("glass").decay(1).sustain(0).release(2).elevation(50).distance(4)
  .delay(.4).delaytime(3/8).delayfeedback(.45).gain(.12)

setcpm(60/4)

// The wind through the bones: the same noise in both ears, one ear phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the old theme
bones: s("white*4").dichotic("<[440 523 659 523] [392 494 587 494] [349 440 523 440] [330 415 494 415]>")
  .dichoticq(30).attack(.02).sustain(1).release(.05).gain(.14)

// A quiet hint: the first bar hummed, once every four bars
hint: note("<[a4 c5 e5 c5] ~ ~ ~>").s("hum").attack(.05).release(.3).gain(.08)

// The hall at night: a ticking clock on the right, a guard's footsteps beyond the wall
clock: s("tick ~ tick ~").azimuth(70).distance(5).space("church").gain(.05)
guard: s("step ~ ~ ~ step ~ ~ ~").azimuth(-110).distance(6).occlude(.6).gain(.1)
creak: s("~ ~ ~ creak").mask("<0 0 1 0 0 0 0 1>").elevation(40).distance(4).gain(.1)

// A low, still drone for the skeletons
drone: note("[a1,e2]").slow(8).s("sine").attack(4).sustain(1).release(6).gain(.18)
